    fetch(&#039;http://localhost/cariin/public/compare/add/&#039; + propertyId, { method: &#039;POST&#039; })
        .then(r =&gt; r.json())
        .then(d =&gt; {
            if (d.ok) {
                if (confirm(&#039;Ditambahkan ke perbandingan (&#039;+d.count+&#039;). Lihat sekarang?&#039;)) {
                    window.location = &#039;http://localhost/cariin/public/compare&#039;;
                }
            } else {
                alert(d.message || &#039;Gagal menambahkan.&#039;);
            }
        });
}

